package com.careflow.hospital.doctors;
import com.careflow.hospital.audit.AuditService; import com.careflow.hospital.departments.*; import com.careflow.hospital.identity.*; import org.junit.jupiter.api.*; import java.util.*; import static org.junit.jupiter.api.Assertions.*; import static org.mockito.ArgumentMatchers.*; import static org.mockito.Mockito.*;
class DoctorOnboardingServiceTest {DoctorApplicationRepository applications=mock(DoctorApplicationRepository.class);DoctorRepository doctors=mock(DoctorRepository.class);DepartmentRepository departments=mock(DepartmentRepository.class);AppUserRepository users=mock(AppUserRepository.class);AuditService audit=mock(AuditService.class);DoctorOnboardingService service;UUID userId=UUID.randomUUID(),departmentId=UUID.randomUUID();
 @BeforeEach void setup(){service=new DoctorOnboardingService(applications,doctors,departments,users,audit);Department department=mock(Department.class);when(department.isActive()).thenReturn(true);when(department.getId()).thenReturn(departmentId);when(departments.findById(departmentId)).thenReturn(Optional.of(department));when(applications.save(any())).thenAnswer(i->i.getArgument(0));when(doctors.save(any())).thenAnswer(i->i.getArgument(0));}
 @Test void applyingDoesNotGrantDoctorRole(){var view=service.apply(userId,new DoctorDtos.Apply("Dr Test","Cardiology",departmentId,"MBBS",8,"LIC-123"));assertEquals("PENDING",view.status());verify(users,never()).save(any());verify(doctors,never()).save(any());}
 @Test void adminApprovalCreatesDoctorAndGrantsRole(){AppUser applicant=new AppUser(userId,"doctor@example.test","hash");DoctorApplication application=new DoctorApplication(userId,"Dr Test","Cardiology",departmentId,"MBBS",8,"LIC-123");UUID adminId=UUID.randomUUID();when(applications.findById(application.getId())).thenReturn(Optional.of(application));when(users.findById(userId)).thenReturn(Optional.of(applicant));var view=service.review(adminId,application.getId(),"APPROVE");assertEquals("APPROVED",view.status());assertTrue(applicant.getRoles().contains("DOCTOR"));verify(doctors).save(any());verify(audit).record(adminId,"DOCTOR_APPLICATION_APPROVE","DOCTOR_APPLICATION",application.getId(),"SUCCESS");}
 @Test void profileReturnsAuthenticatedDoctorsProfessionalDetails(){Doctor doctor=mock(Doctor.class);Department department=mock(Department.class);when(doctor.getDepartmentId()).thenReturn(departmentId);when(doctor.getFullName()).thenReturn("Dr Test");when(doctor.getSpecialization()).thenReturn("Cardiology");when(department.getId()).thenReturn(departmentId);when(department.getName()).thenReturn("Cardiology");when(doctors.findByUserId(userId)).thenReturn(Optional.of(doctor));when(departments.findById(departmentId)).thenReturn(Optional.of(department));var profile=service.profile(userId);assertEquals("Dr Test",profile.fullName());assertEquals("Cardiology",profile.departmentName());}
}
